{"kind": "content", "icon": "🗞️", "head": "कहानी से पहले: चौपाल का अख़बार", "points": ["गाँव की चौपाल पर एक अख़बार", "दादाजी ज़ोर से पढ़ते, सब सुनते", "मंडी भाव, मौसम, सरकारी योजना", "बहस भी, जानकारी भी", "एक अख़बार, पूरा गाँव जागरूक"], "say": "पहले गाँव की चौपाल पर सुबह एक अख़बार आता था। दादाजी ज़ोर से पढ़ते और पूरा टोला सुनता। मंडी में धान का भाव, बारिश का अनुमान, नई सरकारी योजना, सब उसी से पता चलता। फिर उस पर बहस होती। एक अख़बार से पूरा गाँव जागरूक हो जाता था। आज मोबाइल पर भी ख़बरें आती हैं, पर अख़बार की भूमिका अब भी बहुत बड़ी है। आज का पाठ इसी भूमिका पर है।"},
{"kind": "content", "icon": "✍️", "head": "लेखक का परिचय", "points": ["के. आर. नारायणन (1920–2005)", "केरल के एक साधारण परिवार में जन्म", "पत्रकार, राजनयिक, सांसद", "भारत के दसवें राष्ट्रपति (1997–2002)", "पहले दलित राष्ट्रपति"], "say": "के आर नारायणन का जन्म केरल के एक ग़रीब परिवार में हुआ। कठिन परिस्थितियों में पढ़ाई करके वे पहले पत्रकार बने और द हिंदू और टाइम्स ऑफ़ इंडिया जैसे अख़बारों में काम किया। फिर विदेश सेवा में राजदूत बने, सांसद बने, और उन्नीस सौ सत्तानवे में भारत के दसवें राष्ट्रपति बने। वे देश के पहले दलित राष्ट्रपति थे। ख़ुद पत्रकार रहने के कारण वे अख़बारों की भूमिका को अच्छी तरह समझते थे।"},
{"kind": "content", "icon": "🎤", "head": "यह एक भाषण है", "points": ["किसी अख़बार के समारोह में", "श्रोताओं को संबोधन", "अनुभव और विचार", "सरल, प्रभावशाली भाषा", "प्रशंसा भी, चेतावनी भी"], "say": "यह पाठ एक भाषण है, जो किसी अख़बार के समारोह में दिया गया। भाषण में वक्ता सीधे श्रोताओं से बात करता है, अपने अनुभव और विचार बताता है। नारायणन अख़बारों की प्रशंसा भी करते हैं और उन्हें उनकी ज़िम्मेदारी की याद भी दिलाते हैं। परीक्षा में पूछा जाए कि यह किस प्रकार की रचना है, तो उत्तर है, अ स्पीच।"},
{"kind": "content", "icon": "🇮🇳", "head": "स्वतंत्रता संग्राम में अख़बार", "points": ["अख़बार – आज़ादी की लड़ाई का हथियार", "तिलक – केसरी", "गांधी – यंग इंडिया, हरिजन", "राष्ट्रीय चेतना जगाई", "कई संपादक जेल गए"], "say": "भारत की आज़ादी की लड़ाई में अख़बार एक बड़ा हथियार थे। बाल गंगाधर तिलक का केसरी, गांधी जी का यंग इंडिया और हरिजन, ऐसे अख़बारों ने लोगों में राष्ट्रीय चेतना जगाई। अंग्रेज़ सरकार उनसे डरती थी, इसलिए कई अख़बार बंद किए गए और संपादकों को जेल भेजा गया। नारायणन याद दिलाते हैं कि भारतीय पत्रकारिता की जड़ें त्याग और देशसेवा में हैं।"},
{"kind": "content", "icon": "🏛️", "head": "लोकतंत्र का चौथा स्तंभ", "points": ["विधायिका, कार्यपालिका, न्यायपालिका", "चौथा – प्रेस (मीडिया)", "सरकार पर नज़र", "जनता की आवाज़", "भ्रष्टाचार उजागर करना"], "say": "लोकतंत्र के तीन स्तंभ हैं, विधायिका जो क़ानून बनाती है, कार्यपालिका जो लागू करती है, और न्यायपालिका जो न्याय करती है। प्रेस यानी अख़बार और मीडिया को चौथा स्तंभ कहते हैं। अख़बार सरकार के कामों पर नज़र रखते हैं, जनता की समस्याएँ सामने लाते हैं और भ्रष्टाचार को उजागर करते हैं। आज़ाद प्रेस के बिना लोकतंत्र अधूरा है।"},
{"kind": "content", "icon": "📈", "head": "विकास में भूमिका", "points": ["योजनाओं की जानकारी गाँव तक", "किसानों को खेती की नई तकनीक", "स्वास्थ्य – टीके, साफ़-सफ़ाई", "शिक्षा, रोज़गार के समाचार", "समस्याएँ सरकार तक"], "say": "नारायणन कहते हैं कि अख़बार देश के विकास में असाधारण भूमिका निभाते हैं। वे सरकारी योजनाओं की जानकारी गाँव गाँव तक पहुँचाते हैं, किसानों को खेती की नई तकनीक बताते हैं, टीकाकरण और साफ़ सफ़ाई के बारे में जागरूक करते हैं, और शिक्षा तथा नौकरी के समाचार देते हैं। साथ ही वे गाँव की सड़क, बिजली और पानी की समस्याएँ सरकार तक पहुँचाते हैं।"},
{"kind": "content", "icon": "🌾", "head": "ग्रामीण भारत की आवाज़", "points": ["ज़्यादातर भारत गाँवों में", "पर अख़बारों में गाँव कम", "ग़रीब, किसान, मज़दूर की कहानियाँ", "विकास की असली तस्वीर", "भाषाई अख़बारों का महत्त्व"], "say": "नारायणन याद दिलाते हैं कि भारत की बड़ी आबादी गाँवों में रहती है, पर अख़बारों में गाँव की ख़बरें कम होती हैं। उनका कहना है कि अख़बारों को ग़रीबों, किसानों और मज़दूरों की कहानियाँ भी छापनी चाहिए, तभी विकास की असली तस्वीर सामने आएगी। इसमें हिंदी, बांग्ला और दूसरी भारतीय भाषाओं के अख़बारों का बहुत बड़ा महत्त्व है, क्योंकि वे आम लोगों की भाषा में बात करते हैं।"},
{"kind": "content", "icon": "⚖️", "head": "अख़बार की ज़िम्मेदारी", "points": ["सच और निष्पक्ष ख़बर", "सनसनी से बचना", "अफ़वाह न फैलाना", "सांप्रदायिक सद्भाव", "विज्ञापन के दबाव में न झुकना"], "say": "अख़बार की ताक़त के साथ उसकी ज़िम्मेदारी भी बड़ी है। नारायणन कहते हैं कि अख़बार को सच और निष्पक्ष ख़बर देनी चाहिए, सनसनी फैलाने के लिए ख़बर को बढ़ा चढ़ाकर नहीं लिखना चाहिए, और कभी ऐसी ख़बर नहीं छापनी चाहिए जिससे समाज में नफ़रत या दंगे फैलें। विज्ञापन देने वालों या ताक़तवर लोगों के दबाव में सच नहीं छिपाना चाहिए।"},
